import java.io.*;

public class Main {
    static int[] reconstructCoins(int n, long[] dp) {
        // Write your solution here
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        long[] dp = new long[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = Long.parseLong(st.nextToken());
        int[] coins = reconstructCoins(n, dp);
        StringBuilder sb = new StringBuilder();
        sb.append(coins.length).append("\n");
        for (int i = 0; i < coins.length; i++) sb.append(coins[i]).append(i + 1 < coins.length ? " " : "\n");
        System.out.print(sb);
    }
}
